script:
html { color-scheme: dark; }
body { background: var(--6aad89d6-6138-430f-b63a-50db36050c49, #0E0F11); }
button { cursor: pointer; }
button:disabled { opacity: 0.4; cursor: not-allowed; }
a, button { transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease, border-color 0.15s ease; }
a:hover { opacity: 0.65; }
:focus-visible { outline: 2px solid var(--34e3bfcb-2aad-4589-8025-160deff3e9d8, #D8FF3E); outline-offset: 2px; }
[data-shop="variant-option"][data-selected="true"] {
	background: var(--34e3bfcb-2aad-4589-8025-160deff3e9d8, #D8FF3E);
	color: var(--6aad89d6-6138-430f-b63a-50db36050c49, #0E0F11);
	border-color: var(--34e3bfcb-2aad-4589-8025-160deff3e9d8, #D8FF3E);
}
[data-shop="cart-count"][data-empty="true"] { display: none; }
input, textarea { font-family: inherit; }
::selection { background: var(--34e3bfcb-2aad-4589-8025-160deff3e9d8, #D8FF3E); color: var(--6aad89d6-6138-430f-b63a-50db36050c49, #0E0F11); }
